-- MediNexus - persistence verification table (TASK-01.03.04)
--
-- Creates the technical table used by the JPA entity
-- com.medinexus.medicore.persistence.entity.PersistenceCheck and by
-- PersistenceCheckRepositoryIntegrationTest. It holds no application or
-- patient data.
--
-- Idempotent: safe to run more than once. It only creates the table when it
-- does not exist yet and never drops or alters existing tables or data.
--
-- Mapping (must match PersistenceCheck.java):
--   id          Long, @Id, @GeneratedValue(IDENTITY) -> BIGINT identity, primary key
--   description String, @Column(nullable = false)     -> VARCHAR(255) NOT NULL
--
-- SUPERSEDED: the table is now created by the Flyway migration
-- src/main/resources/db/migration/V1__create_persistence_check.sql.
-- Kept for reference only. Do NOT run this on a new database: Flyway would
-- then find a non-empty schema without history and refuse to start.
-- See infrastructure/database/README.md, section "Database migrations (Flyway)".

CREATE TABLE IF NOT EXISTS persistence_check (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    description VARCHAR(255) NOT NULL
);
